:root{--brand:<?= e($store['primary_color']) ?>;--bg:<?= e($store['background_color']) ?>;--soft:<?= e($store['surface_color']) ?>;--ink:<?= e($store['text_color']) ?>;--muted:<?= e($store['muted_color']) ?>;--line:color-mix(in srgb,var(--ink) 12%,transparent);--radius:<?= (int)$store['border_radius'] ?>px}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font:15px/1.55 Inter,system-ui,sans-serif}.container{width:min(760px,calc(100% - 28px));margin:auto}.header{height:76px;background:<?= e($store['header_color']) ?>;border-bottom:1px solid var(--line);display:flex;align-items:center}.brand{font-size:19px;font-weight:950;color:inherit;text-decoration:none}.page{padding:54px 0 80px}.card{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);padding:clamp(24px,5vw,42px);box-shadow:0 22px 65px color-mix(in srgb,var(--ink) 10%,transparent)}.status{width:72px;height:72px;border-radius:50%;display:grid;place-items:center;background:<?= $isPaid?'#dcfce7':'color-mix(in srgb,var(--brand) 13%,white)' ?>;color:<?= $isPaid?'#15803d':'var(--brand)' ?>;font-size:32px;margin:auto}.intro{text-align:center}.intro h1{font-size:clamp(28px,5vw,40px);line-height:1.1;margin:18px 0 10px}.intro p{color:var(--muted);margin:0}.number{display:inline-block;margin-top:17px;padding:8px 13px;border-radius:10px;background:var(--soft);font-weight:950}.items{margin-top:34px;border-top:1px solid var(--line)}.item,.line,.total{display:flex;justify-content:space-between;gap:20px;padding:13px 0}.item{border-bottom:1px solid var(--line)}.item span{color:var(--muted)}.totals{margin-top:12px}.line{color:var(--muted)}.total{border-top:1px solid var(--line);font-size:20px;font-weight:950}.note{margin-top:25px;padding:15px;border-radius:12px;background:var(--soft);color:var(--muted)}.actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:28px}.button{min-height:48px;display:inline-flex;align-items:center;padding:0 20px;border-radius:12px;background:var(--brand);color:white;font-weight:900;text-decoration:none}.button.secondary{background:transparent;color:var(--brand);border:1px solid var(--brand)}footer{padding:26px;text-align:center;color:var(--muted);font-size:12px}</style></head><body>
<header class="header"><div class="container"><a class="brand" href="/store/<?= e($store['slug']) ?>"><?= e($store['store_name']) ?></a></div></header><main class="page"><div class="container"><article class="card"><div class="intro"><div class="status"><?= $isPaid?'✓':'✓' ?></div><h1><?= $isPaid?'¡Pago confirmado!':'¡Pedido recibido!' ?></h1><p><?= $isPaid?'Tu pago fue procesado correctamente.':'La tienda recibió tu orden y se comunicará contigo para continuar.' ?></p><span class="number"><?= e($order['order_number']) ?></span></div><div class="items"><?php foreach($order['items'] as $item): ?><div class="item"><div><strong><?= e($item['product_name']) ?></strong><span> × <?= (int)$item['quantity'] ?></span></div><strong><?= e($symbol) ?> <?= number_format((float)$item['line_total'],2) ?></strong></div><?php endforeach; ?></div><div class="totals"><div class="line"><span>Subtotal</span><strong><?= e($symbol) ?> <?= number_format((float)$order['subtotal'],2) ?></strong></div><div class="line"><span>Envío</span><strong><?= e($symbol) ?> <?= number_format((float)$order['shipping_total'],2) ?></strong></div><div class="total"><span>Total</span><span><?= e($symbol) ?> <?= number_format((float)$order['total'],2) ?></span></div></div><div class="note"><strong>Estado del pago:</strong> <?= e(match($order['payment_status']){'paid'=>'Pagado','awaiting_payment'=>'Pendiente de pago','pending_external'=>'Esperando confirmación del proveedor',default=>'Pendiente'}) ?>.<br>Conserva el número del pedido para cualquier consulta.</div><div class="actions"><a class="button" href="/store/<?= e($store['slug']) ?>">Seguir comprando</a><?php if($store['whatsapp']): ?><a class="button secondary" target="_blank" rel="noopener" href="https://wa.me/<?= e(preg_replace('/\D+/','',$store['whatsapp'])) ?>?text=<?= rawurlencode('Hola, deseo consultar el pedido '.$order['order_number']) ?>">Consultar por WhatsApp</a><?php endif; ?></div></article></div></main><footer><?= e($store['footer_text'] ?: